#!/usr/bin/env python3
"""Differential test: submission/main.py vs tmp/ref.py on generated inputs."""
import json
import subprocess
import sys

sys.path.insert(0, "/app/tmp")
import gen


def run(script, payload):
    p = subprocess.run([sys.executable, script], input=payload.encode(),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.returncode, p.stdout


def main():
    lo = int(sys.argv[1])
    hi = int(sys.argv[2])
    bad = 0
    stats = {}
    for seed in range(lo, hi):
        doc = gen.gen(seed)
        payload = json.dumps(doc)
        rc1, out1 = run("/app/submission/main.py", payload)
        rc2, out2 = run("/app/tmp/ref.py", payload)
        if rc1 != 0 or rc2 != 0:
            print("seed", seed, "nonzero exit", rc1, rc2)
            bad += 1
            continue
        try:
            a = json.loads(out1)
        except Exception as e:
            print("seed", seed, "sub output not json", e, out1[:200])
            bad += 1
            continue
        try:
            b = json.loads(out2)
        except Exception as e:
            print("seed", seed, "ref output not json", e, out2[:200])
            bad += 1
            continue
        for p in a["packets"]:
            stats[p["decision"]] = stats.get(p["decision"], 0) + 1
        if a != b:
            bad += 1
            print("=== MISMATCH seed", seed)
            for k in ("packets", "jobs", "connections", "reports"):
                if a[k] != b[k]:
                    print(" field", k)
                    if k == "packets":
                        for x, y in zip(a[k], b[k]):
                            if x != y:
                                print("  sub:", x)
                                print("  ref:", y)
                                break
                    elif k == "jobs":
                        for x, y in zip(a[k], b[k]):
                            if x != y:
                                print("  sub:", x)
                                print("  ref:", y)
                                break
                    else:
                        print("  sub:", json.dumps(a[k])[:600])
                        print("  ref:", json.dumps(b[k])[:600])
            if bad > 3:
                break
    print("checked", hi - lo, "seeds, mismatches:", bad)
    print("decision coverage:", stats)


if __name__ == "__main__":
    main()
