from fractions import Fraction
def ref(z,s):
    q=Fraction(z,1)/(2**s)
    neg = q<0
    aq = -q if neg else q
    fl = aq.numerator//aq.denominator
    rem = aq-fl
    r = fl+1 if rem>=Fraction(1,2) else fl
    return -r if neg else r
def mine(z,s):
    if s==0: return z
    d=1<<s; h=d>>1
    if z>=0: return (z+h)//d
    return -((-z+h)//d)
bad=0; n=0
